from author import *
b=[]
def add(a,n,ops,focus='viewport'):b.append(act(a,n,ops,focus))
def p(k,v,node='Particles',**kw):return setp(k,v,node,**kw)
def proc(k,v,node='Particles'):
 return p(k,v,node,resource_property='process_material',restart=True,filter=k.replace('_',' '))
def draw(k,v,node='Particles'):
 return p(k,v,node,resource_property='draw_pass_1',resource_chain=['material'],filter=k.replace('_',' '))
def view(angle=45,orbit=False):return dict(op='view3d',angle=angle,orbit=orbit)
def new(kind,**props):return {'new':kind,'props':props}
sphere=new('SphereMesh',radius=.12,height=.24,radial_segments=12,rings=6,material=new('StandardMaterial3D',albedo_color={'color':'ffffff'}))
A='Add Depth And A Draw Pass'
add(A,'This is the three-dimensional test stage. The floor and the one-meter reference stay fixed while we change the effect. We are using Godot’s Compatibility renderer. The camera will move so depth has to survive more than one flattering angle.',[dict(op='open',path='res://arena.tscn'),at(.5,**view())])
add(A,'Add G P U Particles Three D. Set Amount to sixty-four. Set Lifetime to two seconds. There is no visible result yet. A particle node needs both a simulation resource and something to draw.',[dict(op='add',class_name='GPUParticles3D',name='Particles',properties={'amount':64,'lifetime':2,'use_fixed_seed':True,'seed':7270,'position':{'v3':[0,.3,0]}},checkpoint=True)])
add(A,'Create a Particle Process Material. This is the behavior resource. It can give particles velocity and gravity, but it is not the surface material that will color a sphere or draw a soft image.',[p('process_material',new('ParticleProcessMaterial')),at(1,op='resource',node='Particles',property='process_material')])
add(A,'Assign a small sphere to Draw Pass One, with a standard surface material. Now the particle positions have visible geometry. This is the separate draw decision: the process material moves particles, and the mesh gives each one a shape.',[p('draw_pass_1',sphere)])
add(A,'Launch upward with positive Y, using a speed range from three to five. Gravity points downward at negative six. That differs from our two-dimensional canvas convention. Watch the spheres rise, slow, and return toward the floor.',[proc('direction',{'v3':[0,1,0]}),at(.3,**proc('initial_velocity_min',3)),at(.6,**proc('initial_velocity_max',5)),at(.9,**proc('gravity',{'v3':[0,-6,0]})),at(1.2,**proc('spread',25))])
add(A,'Orbit the editor camera. The particles occupy a volume, and the spheres keep their shape as our viewpoint changes. The camera motion is scripted for this recording; the scene and its particle simulation are running in the real editor.',[view(45,True)])
add(A,'Here is a staged drawing fault. Remove Draw Pass One. The emission and process resource still exist, but the spheres disappear. More amount or more speed would not repair a missing draw mesh.',[view(45,False),at(.3,**p('draw_pass_1',None))])
add(A,'Restore the sphere and the picture returns. Save this checkpoint. When an effect is missing, separate three questions: are particles being emitted, are they moving where expected, and does the draw setup make them visible?',[p('draw_pass_1',sphere),at(1,op='save',checkpoint=True)])
A='Make Shape And Color Read'
add(A,'Change the emission shape from a point to a box. The particles are now born across a region, instead of sharing one exact source. The box controls birth positions; it does not replace the launch direction.',[setp('heading',A),at(.3,**proc('emission_shape',3)),at(.6,**proc('emission_box_extents',{'v3':[.8,.1,.8]}))])
add(A,'Compare a sphere-shaped emission volume with the box, then restore the box. Shape changes where the effect begins. Keep speed, lifetime, and gravity fixed during this comparison so that one visible difference has one explanation.',[proc('emission_shape',1),at(.3,**proc('emission_sphere_radius',.8)),at(5,**proc('emission_shape',3))])
add(A,'Reverse the launch direction for a moment. Negative Y sends the initial motion down toward the floor. Restore positive Y. A direction is only meaningful in the coordinate system of this scene, not from the word up in our notes.',[proc('direction',{'v3':[0,-1,0]}),at(5,**proc('direction',{'v3':[0,1,0]}))])
add(A,'Set gravity to zero. The particles keep traveling along their launch motion. Restore negative six and the path bends back down. Gravity changes the velocity over time; it is not another name for the initial speed.',[proc('gravity',{'v3':[0,0,0]}),at(5,**proc('gravity',{'v3':[0,-6,0]}))])
add(A,'Set a controlled scale range, from four tenths to one. The same sphere mesh now produces varied sizes. The one-meter reference makes that choice visible in scene units. Variation should support a readable effect, rather than conceal a weak silhouette.',[proc('scale_min',.4),at(.3,**proc('scale_max',1))])
add(A,'Assign a hot-to-cool color ramp in the process material. The spheres stay white because their draw material is not using particle vertex colors yet. This is a deliberately staged connection fault between simulation data and appearance.',[proc('color_ramp',{'resource':'res://assets/hot-fade.tres'}),at(1,op='resource',node='Particles',property='process_material',resource_chain=['color_ramp','gradient'])])
add(A,'Enable Vertex Color Use As Albedo in the sphere’s material. Now the same particle color data reaches the visible mesh. The process ramp and the draw material have to agree about which data becomes the picture.',[draw('vertex_color_use_as_albedo',True)])
add(A,'The ramp ends at zero alpha, but an opaque material does not show that fade. Switch transparency to Alpha. The spheres now fade as they age. Color, transparency mode, and particle lifetime are related choices with different jobs.',[draw('transparency',1),at(4,**draw('transparency',0)),at(8,**draw('transparency',1))])
A='Make Soft Particles'
add(A,'Duplicate the emitter as Smoke, then make its process material unique. Put the two sources beside each other. We will keep their different visual jobs visible while changing the smoke’s drawing and motion.',[setp('heading',A),at(.3,op='duplicate',node='Particles',name='Smoke',properties={'position':{'v3':[2,.3,0]}}),at(.6,op='unique',node='Smoke',property='process_material'),at(.9,**p('position',{'v3':[-2,.3,0]}))])
add(A,'Replace the smoke’s sphere with a quad and our procedural soft-dot texture. Its material is unshaded and uses alpha transparency. This is a flat image placed in three dimensions; it will need a deliberate camera-facing setup.',[p('draw_pass_1',new('QuadMesh',size={'v2':[.7,.7]},material=new('StandardMaterial3D',shading_mode=0,transparency=1,vertex_color_use_as_albedo=True,albedo_texture={'resource':'res://assets/soft-dot.tres'})),'Smoke')])
add(A,'Orbit with billboarding off and the flat cards turn away from us. Enable particle billboarding and Keep Scale. The cards face the camera while preserving the particle size. This repairs the view-dependent silhouette without turning each card into a sphere.',[view(45,True),at(4,**draw('billboard_mode',3,'Smoke')),at(4.4,**draw('billboard_keep_scale',True,'Smoke'))])
add(A,'Give the smoke a slow upward speed, narrow spread, and zero gravity. Replace the hot ramp with a muted smoke ramp. The two effects now share a particle model but communicate different material behavior.',[view(45,False),at(.3,**proc('initial_velocity_min',.5,'Smoke')),at(.6,**proc('initial_velocity_max',1,'Smoke')),at(.9,**proc('gravity',{'v3':[0,0,0]},'Smoke')),at(1.2,**proc('spread',12,'Smoke')),at(1.5,**proc('color_ramp',{'resource':'res://assets/smoke-fade.tres'},'Smoke'))])
add(A,'Attach the growth curve and increase the smoke’s scale. New particles start small and expand as they rise. A curve expresses a change over age, while the random scale range supplies variation between individual particles.',[proc('scale_min',1.5,'Smoke'),at(.3,**proc('scale_max',2.2,'Smoke')),at(.6,**proc('scale_curve',{'resource':'res://assets/grow.tres'},'Smoke')),at(1,op='resource',node='Smoke',property='process_material',resource_chain=['scale_curve','curve'])])
add(A,'Compare additive blending with ordinary alpha blending. Additive smoke brightens the background, which changes its visual meaning. Restore alpha for this plume. Choose a blend mode for what the effect represents, then inspect it in the lighting where it will be used.',[draw('blend_mode',1,'Smoke'),at(5,**draw('blend_mode',0,'Smoke'))])
add(A,'Orbit both results together. Mesh particles remain small solid forms; the smoke remains soft camera-facing imagery. Neither drawing method is universally better. The visible job and camera distance determine which one earns its cost.',[view(45,True),at(8,**view(45,False)),at(9,op='save',checkpoint=True)])
A='Make The Effect Survive The Scene'
add(A,'Move the original emitter with local coordinates off. New particles appear at the moving source, while older particles stay in world space. This is the behavior needed for a trail left behind an object.',[setp('heading',A),at(.3,**setp('move_source',True)),at(.6,**p('local_coords',False))])
add(A,'Turn local coordinates on and the existing cloud follows the source. Turn them off again. Both behaviors are useful, but they tell different stories: an attached aura moves with its owner, while a trail records where that owner has been.',[p('local_coords',True),at(5,**p('local_coords',False)),at(9,**setp('move_source',False))])
add(A,'Shrink the visibility box, then restore a box that covers the measured motion. The box is a culling bound, not a wall for the particles. Inspect it from the camera angles the game can actually reach.',[p('visibility_aabb',{'aabb':[-.1,-.1,-.1,.2,.2,.2]}),at(5,**p('visibility_aabb',{'aabb':[-5,-5,-5,10,10,10]})),at(8,**view(100,False))])
add(A,'Duplicate Smoke as Shared Smoke without making its process material unique. Change the duplicate’s launch speed and both plumes change. That is a shared resource doing exactly what sharing means; the mistake is expecting independent behavior.',[view(),at(.3,op='duplicate',node='Smoke',name='SharedSmoke',properties={'position':{'v3':[-2,.3,-2]}}),at(.6,**proc('initial_velocity_max',3,'SharedSmoke'))])
add(A,'Make the duplicate’s process material unique, then reduce only its speed. Its original partner keeps the faster setting. Keep intentional texture sharing, but separate the behavior resource that needs an independent edit.',[dict(op='unique',node='SharedSmoke',property='process_material'),at(.4,**proc('initial_velocity_max',.7,'SharedSmoke')),at(5,**p('visible',False,'SharedSmoke')),at(5.3,**p('visible',False,'Smoke'))])
add(A,'For the collision experiment, put the emitter above the floor and aim it down. Add a particle collision box that matches the floor’s top. A visible floor mesh alone does not establish particle collision.',[p('position',{'v3':[0,3,0]}),at(.3,**proc('direction',{'v3':[0,-1,0]})),at(.6,**proc('initial_velocity_min',1)),at(.9,**proc('initial_velocity_max',2)),at(1.2,**p('lifetime',2.5)),at(1.5,op='add',class_name='GPUParticlesCollisionBox3D',name='ParticleFloor',properties={'position':{'v3':[0,-.2,0]},'size':{'v3':[10,.4,10]}})])
add(A,'Enable rigid collision in the particle process material and give it a visible bounce. Now compare the floor contact with collision disabled, then restore collision. This box setup is supported by the renderer used for this recorded test.',[proc('collision_mode',1),at(.3,**proc('collision_bounce',.5)),at(5,**proc('collision_mode',0)),at(9,**proc('collision_mode',1))])
add(A,'Orbit the contact area. The particle collision box affects the visual simulation; it does not award damage or change the game’s rules. Keep gameplay decisions in gameplay code, even when a particle bounce helps sell the event.',[view(45,True),at(8,**view(45,False))])
add(A,'Keep renderer requirements with the effect. This box example does not establish support for signed-distance-field collision, trails, or every GPU feature. A clean offline capture is also not a frame-time measurement on the target device.',[dict(op='select',node='ParticleFloor'),at(5,op='select',node='Particles')])
add(A,'Save the stage and separate mesh and smoke scenes. The useful result includes the draw setup, motion resource, coordinate choice, and bounds. Those choices can now be tested together when the effects enter a real game.',[p('visible',True,'Smoke'),at(.3,op='save_branch',node='Particles',path='res://effects/mesh-sparks.tscn'),at(.6,op='save_branch',node='Smoke',path='res://effects/soft-smoke.tscn'),at(1,op='save',checkpoint=True)])
d=dict(slug='claude-liam-lecture-building-3d-particle-effects-in-godot',title='Building 3D Particle Effects in Godot',payoff='Build readable mesh and billboard effects',summary='Connect motion, meshes, and materials, then test particles from several angles.',framing='Does a particle effect become three-dimensional just because its node says Three D? We will build the missing draw setup and inspect what survives a moving camera.',question='A particle node is\nthe whole effect',trigger='whole',replacement='start of an',terms=[dict(term='Mesh',meaning='The geometry drawn for a particle'),dict(term='Material',meaning='A resource for behavior or appearance'),dict(term='Camera',meaning='The view through which the scene is seen'),dict(term='Axis',meaning='One direction in a coordinate system')],body=b,recap=['A 3D emitter needs behavior and a draw mesh.','Emission shape, velocity, and gravity have separate jobs.','Vertex color and transparency connect particle data to appearance.','Billboards keep soft images readable as the camera moves.','Coordinate space, bounds, and resource ownership need deliberate choices.','Visual collision does not replace gameplay rules.'],prompt='Create mesh sparks and soft smoke from the same launch behavior. Predict what changes when the camera moves, then test both effects from several angles and preserve a revision.',checks=['Check: both effects remain readable as the camera moves.','Check: the draw setup explains their different appearance.'],coverage='Four acts cover explicit 3D node/process/draw construction; a missing-draw-pass fault and repair; multiple angles; emission shapes, launch, gravity and scale; vertex colors and transparency; procedural textured quads and particle billboarding with preserved scale; smoke and mesh comparison; local/world coordinates; visibility AABB; unwanted shared edits and unique process resources; a native supported box-collision experiment; packaging and renderer limits.',facts='Godot 3D positive Y is up. Material enum values must be checked on installed Godot 4.7.2 before narration generation. Collision behavior and visibility require a real-renderer pilot before accepting these statements. The box experiment uses Compatibility only if its observed behavior supports the claim. SDF support is not inferred from a box test.',sources='Original 3D stage and procedural resources. https://docs.godotengine.org/en/stable/tutorials/3d/particles/creating_a_3d_particle_system.html\nhttps://docs.godotengine.org/en/stable/tutorials/3d/particles/collision.html\nhttps://docs.godotengine.org/en/stable/classes/class_gpuparticlescollisionbox3d.html\nhttps://docs.godotengine.org/en/stable/classes/class_gpuparticles3d.html')
if __name__=='__main__':Path('film3.json').write_text(json.dumps(d,indent=2));author(d)
